CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Sign-in identity for a sales user.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Name shown as the record owner throughout the UI.
	"full_name" VARCHAR(160) NOT NULL,
	-- rep | manager | admin. Managers see their reports rollup; the hierarchy below is what makes that resolvable.
	"role" VARCHAR(24) NOT NULL DEFAULT 'rep',
	-- Who this user rolls up to. Self-reference, null at the top of the tree.
	"manager_id" BIGINT,
	-- Default territory. Null for overlay roles such as solutions engineers who work every territory.
	"territory_id" BIGINT,
	-- Period quota in minor units, used as the denominator of attainment.
	"quota_minor" BIGINT,
	-- Deactivated users keep ownership of closed history; reassignment only touches open records.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A salesperson. The manager self-reference is the backbone of forecast rollups, which is why it lives here rather than in a separate hierarchy table.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."email" IS 'Sign-in identity for a sales user.';
COMMENT ON COLUMN "users"."full_name" IS 'Name shown as the record owner throughout the UI.';
COMMENT ON COLUMN "users"."role" IS 'rep | manager | admin. Managers see their reports rollup; the hierarchy below is what makes that resolvable.';
COMMENT ON COLUMN "users"."manager_id" IS 'Who this user rolls up to. Self-reference, null at the top of the tree.';
COMMENT ON COLUMN "users"."territory_id" IS 'Default territory. Null for overlay roles such as solutions engineers who work every territory.';
COMMENT ON COLUMN "users"."quota_minor" IS 'Period quota in minor units, used as the denominator of attainment.';
COMMENT ON COLUMN "users"."is_active" IS 'Deactivated users keep ownership of closed history; reassignment only touches open records.';

CREATE TABLE IF NOT EXISTS "territories" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Display name, e.g. "EMEA Mid-Market".
	"name" VARCHAR(160) NOT NULL,
	-- Parent territory, so regions nest inside theatres. Null at the root.
	"parent_id" BIGINT,
	-- Criteria that route a new account here: country, industry, employee band. JSON because the rule set is edited wholesale each planning cycle.
	"assignment_rules" JSONB,
	-- Retired territories stay so last year numbers still resolve.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "territories" IS 'The routing dimension for ownership. Territories are kept separate from the user hierarchy because coverage is reorganised every year while the reporting lines are not.';
COMMENT ON COLUMN "territories"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "territories"."name" IS 'Display name, e.g. "EMEA Mid-Market".';
COMMENT ON COLUMN "territories"."parent_id" IS 'Parent territory, so regions nest inside theatres. Null at the root.';
COMMENT ON COLUMN "territories"."assignment_rules" IS 'Criteria that route a new account here: country, industry, employee band. JSON because the rule set is edited wholesale each planning cycle.';
COMMENT ON COLUMN "territories"."is_active" IS 'Retired territories stay so last year numbers still resolve.';

CREATE TABLE IF NOT EXISTS "accounts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Company name as it should appear on a quote.
	"name" VARCHAR(200) NOT NULL,
	-- Primary web domain. The only reliable deduplication key a CRM has; company names are not unique and are typed inconsistently.
	"domain" VARCHAR(160) UNIQUE,
	-- Account owner. Null while the account sits in an unassigned pool.
	"owner_user_id" BIGINT,
	-- Territory the account falls in, which drives routing and quota credit.
	"territory_id" BIGINT,
	-- Segment used for reporting and for territory rules.
	"industry" VARCHAR(80),
	-- Headcount band input, the usual proxy for deal size.
	"employee_count" INTEGER,
	-- Reported revenue in minor units, used for segmentation rather than billing.
	"annual_revenue_minor" BIGINT,
	-- ISO 4217 for the revenue figure above.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Parent company, so subsidiaries roll up. Self-reference, null for independents.
	"parent_account_id" BIGINT,
	-- Values for the definitions in custom_field_definitions. Every CRM grows fields nobody anticipated, and each one must not be a migration.
	"custom_fields" JSONB,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "accounts" IS 'The company you sell to. It is deliberately long-lived: deals, contacts and activities all hang off it, so the account row accumulates the relationship history that outlasts any individual opportunity.';
COMMENT ON COLUMN "accounts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "accounts"."name" IS 'Company name as it should appear on a quote.';
COMMENT ON COLUMN "accounts"."domain" IS 'Primary web domain. The only reliable deduplication key a CRM has; company names are not unique and are typed inconsistently.';
COMMENT ON COLUMN "accounts"."owner_user_id" IS 'Account owner. Null while the account sits in an unassigned pool.';
COMMENT ON COLUMN "accounts"."territory_id" IS 'Territory the account falls in, which drives routing and quota credit.';
COMMENT ON COLUMN "accounts"."industry" IS 'Segment used for reporting and for territory rules.';
COMMENT ON COLUMN "accounts"."employee_count" IS 'Headcount band input, the usual proxy for deal size.';
COMMENT ON COLUMN "accounts"."annual_revenue_minor" IS 'Reported revenue in minor units, used for segmentation rather than billing.';
COMMENT ON COLUMN "accounts"."currency_code" IS 'ISO 4217 for the revenue figure above.';
COMMENT ON COLUMN "accounts"."parent_account_id" IS 'Parent company, so subsidiaries roll up. Self-reference, null for independents.';
COMMENT ON COLUMN "accounts"."custom_fields" IS 'Values for the definitions in custom_field_definitions. Every CRM grows fields nobody anticipated, and each one must not be a migration.';
COMMENT ON COLUMN "accounts"."created_at" IS 'Creation time.';

CREATE INDEX "idx_accounts_owner"
ON "accounts" ("owner_user_id");
CREATE INDEX "idx_accounts_territory"
ON "accounts" ("territory_id");

CREATE TABLE IF NOT EXISTS "contacts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Employer. Null for a person you know before you know where they work.
	"account_id" BIGINT,
	-- Given name, used in every email template.
	"first_name" VARCHAR(120) NOT NULL,
	-- Family name.
	"last_name" VARCHAR(120) NOT NULL,
	-- Work address. Not unique, because the same person can legitimately appear under two accounts after a job change.
	"email" VARCHAR(320),
	-- Direct line. Free text, since international formats defeat every normalisation attempt.
	"phone" VARCHAR(40),
	-- Job title, the crude proxy for buying authority.
	"title" VARCHAR(160),
	-- Main point of contact at the account. One per account by convention, enforced in the application.
	"is_primary" BOOLEAN NOT NULL DEFAULT false,
	-- Per-deployment attributes, same mechanism as on accounts.
	"custom_fields" JSONB,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "contacts" IS 'A person at a company. Kept distinct from leads on purpose: a contact is someone you have a relationship with, a lead is someone you are still qualifying, and merging the two makes every pipeline report meaningless.';
COMMENT ON COLUMN "contacts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "contacts"."account_id" IS 'Employer. Null for a person you know before you know where they work.';
COMMENT ON COLUMN "contacts"."first_name" IS 'Given name, used in every email template.';
COMMENT ON COLUMN "contacts"."last_name" IS 'Family name.';
COMMENT ON COLUMN "contacts"."email" IS 'Work address. Not unique, because the same person can legitimately appear under two accounts after a job change.';
COMMENT ON COLUMN "contacts"."phone" IS 'Direct line. Free text, since international formats defeat every normalisation attempt.';
COMMENT ON COLUMN "contacts"."title" IS 'Job title, the crude proxy for buying authority.';
COMMENT ON COLUMN "contacts"."is_primary" IS 'Main point of contact at the account. One per account by convention, enforced in the application.';
COMMENT ON COLUMN "contacts"."custom_fields" IS 'Per-deployment attributes, same mechanism as on accounts.';
COMMENT ON COLUMN "contacts"."created_at" IS 'Creation time.';

CREATE INDEX "idx_contacts_account"
ON "contacts" ("account_id");
CREATE INDEX "idx_contacts_email"
ON "contacts" ("email");

CREATE TABLE IF NOT EXISTS "leads" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- As supplied, often by a web form and often incomplete.
	"first_name" VARCHAR(120),
	-- As supplied.
	"last_name" VARCHAR(120),
	-- As supplied. Not a contact reference, because at this point there may be no company, no account and no relationship.
	"email" VARCHAR(320),
	-- Free text. The whole point of a lead is that the account does not exist yet.
	"company_name" VARCHAR(200),
	-- webinar | inbound | outbound | referral | event | partner. The input to every channel attribution report.
	"source" VARCHAR(40),
	-- new | working | nurturing | qualified | disqualified. Only qualified leads convert.
	"status" VARCHAR(20) NOT NULL DEFAULT 'new',
	-- Fit and engagement score. Null until the scoring job has seen enough signal.
	"score" SMALLINT,
	-- Assigned rep. Null while the lead sits in a shared queue.
	"owner_user_id" BIGINT,
	-- no_budget | no_authority | bad_fit | competitor | unresponsive. The most valuable column for fixing the top of the funnel.
	"disqualified_reason" VARCHAR(60),
	-- Conversion time. Non-null is what makes the lead read-only from then on.
	"converted_at" TIMESTAMP,
	-- Account created or matched at conversion.
	"converted_account_id" BIGINT,
	-- Contact created at conversion.
	"converted_contact_id" BIGINT,
	-- Deal created at conversion. Null when a lead converts to a relationship without an immediate opportunity.
	"converted_deal_id" BIGINT,
	-- When the lead arrived, the start of the speed-to-lead clock.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "leads" IS 'An unqualified enquiry, stored as flat text rather than as references. Conversion writes the three pointers above and freezes the row instead of deleting it, so funnel maths still works: the lead is the only place that remembers the campaign, the source and how long qualification took.';
COMMENT ON COLUMN "leads"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "leads"."first_name" IS 'As supplied, often by a web form and often incomplete.';
COMMENT ON COLUMN "leads"."last_name" IS 'As supplied.';
COMMENT ON COLUMN "leads"."email" IS 'As supplied. Not a contact reference, because at this point there may be no company, no account and no relationship.';
COMMENT ON COLUMN "leads"."company_name" IS 'Free text. The whole point of a lead is that the account does not exist yet.';
COMMENT ON COLUMN "leads"."source" IS 'webinar | inbound | outbound | referral | event | partner. The input to every channel attribution report.';
COMMENT ON COLUMN "leads"."status" IS 'new | working | nurturing | qualified | disqualified. Only qualified leads convert.';
COMMENT ON COLUMN "leads"."score" IS 'Fit and engagement score. Null until the scoring job has seen enough signal.';
COMMENT ON COLUMN "leads"."owner_user_id" IS 'Assigned rep. Null while the lead sits in a shared queue.';
COMMENT ON COLUMN "leads"."disqualified_reason" IS 'no_budget | no_authority | bad_fit | competitor | unresponsive. The most valuable column for fixing the top of the funnel.';
COMMENT ON COLUMN "leads"."converted_at" IS 'Conversion time. Non-null is what makes the lead read-only from then on.';
COMMENT ON COLUMN "leads"."converted_account_id" IS 'Account created or matched at conversion.';
COMMENT ON COLUMN "leads"."converted_contact_id" IS 'Contact created at conversion.';
COMMENT ON COLUMN "leads"."converted_deal_id" IS 'Deal created at conversion. Null when a lead converts to a relationship without an immediate opportunity.';
COMMENT ON COLUMN "leads"."created_at" IS 'When the lead arrived, the start of the speed-to-lead clock.';

CREATE INDEX "idx_leads_status_owner"
ON "leads" ("status", "owner_user_id");
CREATE INDEX "idx_leads_email"
ON "leads" ("email");

CREATE TABLE IF NOT EXISTS "pipeline_stages" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Groups stages into a named pipeline, e.g. new_business or renewals, without a separate parent table.
	"pipeline_key" VARCHAR(40) NOT NULL DEFAULT 'default',
	-- Stage name shown on the board, e.g. "Proposal".
	"name" VARCHAR(120) NOT NULL,
	-- Order in the pipeline. Gaps are allowed so a stage can be inserted without renumbering.
	"position" SMALLINT NOT NULL,
	-- Default win likelihood at this stage, the multiplier behind weighted pipeline.
	"probability_percent" SMALLINT NOT NULL DEFAULT 0,
	-- Marks the terminal winning stage. Reporting keys on this flag rather than on a stage name someone will rename.
	"is_won" BOOLEAN NOT NULL DEFAULT false,
	-- Marks a terminal losing stage.
	"is_lost" BOOLEAN NOT NULL DEFAULT false,
	-- What must be true to enter, written down so two reps mean the same thing by "Proposal".
	"entry_criteria" TEXT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "pipeline_stages" IS 'The stages a deal moves through. A separate pipelines table earns its place only when pipelines need their own permissions and owners; until then the key column groups them and every deal still references a concrete stage row.';
COMMENT ON COLUMN "pipeline_stages"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "pipeline_stages"."pipeline_key" IS 'Groups stages into a named pipeline, e.g. new_business or renewals, without a separate parent table.';
COMMENT ON COLUMN "pipeline_stages"."name" IS 'Stage name shown on the board, e.g. "Proposal".';
COMMENT ON COLUMN "pipeline_stages"."position" IS 'Order in the pipeline. Gaps are allowed so a stage can be inserted without renumbering.';
COMMENT ON COLUMN "pipeline_stages"."probability_percent" IS 'Default win likelihood at this stage, the multiplier behind weighted pipeline.';
COMMENT ON COLUMN "pipeline_stages"."is_won" IS 'Marks the terminal winning stage. Reporting keys on this flag rather than on a stage name someone will rename.';
COMMENT ON COLUMN "pipeline_stages"."is_lost" IS 'Marks a terminal losing stage.';
COMMENT ON COLUMN "pipeline_stages"."entry_criteria" IS 'What must be true to enter, written down so two reps mean the same thing by "Proposal".';

CREATE UNIQUE INDEX "uq_stage_pipeline_position"
ON "pipeline_stages" ("pipeline_key", "position");

CREATE TABLE IF NOT EXISTS "deals" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Company the deal is with.
	"account_id" BIGINT NOT NULL,
	-- Main champion. Null early on, when you have a company but no name.
	"primary_contact_id" BIGINT,
	-- Rep credited with the deal and measured against quota by it.
	"owner_user_id" BIGINT NOT NULL,
	-- Current stage. The denormalised head of deal_stage_history, kept here so a board query is one read.
	"stage_id" BIGINT NOT NULL,
	-- Opportunity name, usually account plus product.
	"name" VARCHAR(200) NOT NULL,
	-- Deal value in minor units. Integer, because a forecast built on floats drifts by real money once summed over thousands of rows.
	"amount_minor" BIGINT NOT NULL DEFAULT 0,
	-- ISO 4217. Multi-currency pipelines convert at report time using the rate of the close date, not of today.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Rep override of the stage default, for the deal the rep knows is better or worse than it looks.
	"probability_percent" SMALLINT,
	-- A local date, not a timestamp — a quarter boundary is a calendar fact and timezone conversion is how a deal slips a quarter by accident.
	"expected_close_date" DATE NOT NULL,
	-- open | won | lost. Redundant with the stage flags, and worth it: every report filters on it.
	"status" VARCHAR(16) NOT NULL DEFAULT 'open',
	-- price | competitor | no_decision | timing | lost_champion. Populated only on loss, and the thing win-rate analysis actually needs.
	"lost_reason" VARCHAR(60),
	-- Origin, carried over from the lead so channel attribution survives conversion.
	"source" VARCHAR(40),
	-- Per-deployment attributes, same mechanism as on accounts.
	"custom_fields" JSONB,
	-- When the opportunity was opened, the start of cycle-time measurement.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When it reached a terminal stage.
	"closed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "deals" IS 'The opportunity. It holds only its current state; how it got here is in deal_stage_history, which is the separation that makes stage conversion rates and cycle times computable at all.';
COMMENT ON COLUMN "deals"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "deals"."account_id" IS 'Company the deal is with.';
COMMENT ON COLUMN "deals"."primary_contact_id" IS 'Main champion. Null early on, when you have a company but no name.';
COMMENT ON COLUMN "deals"."owner_user_id" IS 'Rep credited with the deal and measured against quota by it.';
COMMENT ON COLUMN "deals"."stage_id" IS 'Current stage. The denormalised head of deal_stage_history, kept here so a board query is one read.';
COMMENT ON COLUMN "deals"."name" IS 'Opportunity name, usually account plus product.';
COMMENT ON COLUMN "deals"."amount_minor" IS 'Deal value in minor units. Integer, because a forecast built on floats drifts by real money once summed over thousands of rows.';
COMMENT ON COLUMN "deals"."currency_code" IS 'ISO 4217. Multi-currency pipelines convert at report time using the rate of the close date, not of today.';
COMMENT ON COLUMN "deals"."probability_percent" IS 'Rep override of the stage default, for the deal the rep knows is better or worse than it looks.';
COMMENT ON COLUMN "deals"."expected_close_date" IS 'A local date, not a timestamp — a quarter boundary is a calendar fact and timezone conversion is how a deal slips a quarter by accident.';
COMMENT ON COLUMN "deals"."status" IS 'open | won | lost. Redundant with the stage flags, and worth it: every report filters on it.';
COMMENT ON COLUMN "deals"."lost_reason" IS 'price | competitor | no_decision | timing | lost_champion. Populated only on loss, and the thing win-rate analysis actually needs.';
COMMENT ON COLUMN "deals"."source" IS 'Origin, carried over from the lead so channel attribution survives conversion.';
COMMENT ON COLUMN "deals"."custom_fields" IS 'Per-deployment attributes, same mechanism as on accounts.';
COMMENT ON COLUMN "deals"."created_at" IS 'When the opportunity was opened, the start of cycle-time measurement.';
COMMENT ON COLUMN "deals"."closed_at" IS 'When it reached a terminal stage.';

CREATE INDEX "idx_deals_owner_status"
ON "deals" ("owner_user_id", "status");
CREATE INDEX "idx_deals_stage_close"
ON "deals" ("stage_id", "expected_close_date");
CREATE INDEX "idx_deals_account"
ON "deals" ("account_id");

CREATE TABLE IF NOT EXISTS "deal_stage_history" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Deal that moved.
	"deal_id" BIGINT NOT NULL,
	-- Previous stage. Null for the first row, when the deal was created.
	"from_stage_id" BIGINT,
	-- Stage entered.
	"to_stage_id" BIGINT NOT NULL,
	-- Who moved it. Null for automation.
	"changed_by_user_id" BIGINT,
	-- Deal value at the moment of the move, snapshotted so a late-stage discount does not rewrite the earlier pipeline.
	"amount_minor_at_change" BIGINT,
	-- When the stage was entered.
	"entered_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When it was left. Null for the current stage, which makes age-in-stage a single subtraction.
	"exited_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "deal_stage_history" IS 'One row per stage transition, with both ends of the interval. This is where stage conversion rates, average time in stage and pipeline-as-of-last-Monday come from — none of which can be reconstructed from a single current-stage column.';
COMMENT ON COLUMN "deal_stage_history"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "deal_stage_history"."deal_id" IS 'Deal that moved.';
COMMENT ON COLUMN "deal_stage_history"."from_stage_id" IS 'Previous stage. Null for the first row, when the deal was created.';
COMMENT ON COLUMN "deal_stage_history"."to_stage_id" IS 'Stage entered.';
COMMENT ON COLUMN "deal_stage_history"."changed_by_user_id" IS 'Who moved it. Null for automation.';
COMMENT ON COLUMN "deal_stage_history"."amount_minor_at_change" IS 'Deal value at the moment of the move, snapshotted so a late-stage discount does not rewrite the earlier pipeline.';
COMMENT ON COLUMN "deal_stage_history"."entered_at" IS 'When the stage was entered.';
COMMENT ON COLUMN "deal_stage_history"."exited_at" IS 'When it was left. Null for the current stage, which makes age-in-stage a single subtraction.';

CREATE INDEX "idx_stage_history_deal"
ON "deal_stage_history" ("deal_id", "entered_at");
CREATE INDEX "idx_stage_history_stage_time"
ON "deal_stage_history" ("to_stage_id", "entered_at");

CREATE TABLE IF NOT EXISTS "activities" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account touched. Denormalised alongside the deal so account-level history survives a deleted opportunity.
	"account_id" BIGINT,
	-- Deal touched. Null for relationship work not tied to an opportunity.
	"deal_id" BIGINT,
	-- Person involved.
	"contact_id" BIGINT,
	-- Rep who did it. Null for automated logging.
	"user_id" BIGINT,
	-- call | email | meeting | note | task | demo. The mix of types per deal is the honest measure of engagement.
	"activity_type" VARCHAR(20) NOT NULL,
	-- Short description shown in the timeline.
	"subject" VARCHAR(255) NOT NULL,
	-- Notes or the email body.
	"body" TEXT,
	-- inbound | outbound. Null for notes and tasks, which have no direction.
	"direction" VARCHAR(12),
	-- When it happened. Null for a task that has not been done.
	"occurred_at" TIMESTAMP,
	-- When a task is due. Null for logged past activity.
	"due_at" TIMESTAMP,
	-- Completion time for a task.
	"completed_at" TIMESTAMP,
	-- Length of a call or meeting.
	"duration_minutes" INTEGER,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "activities" IS 'Everything that happened, past and future, in one timeline. Calls, emails and meetings share a table because the interesting queries — last touch, days since contact, activity per stage — all want them interleaved, and a task is just an activity whose occurred_at is still null.';
COMMENT ON COLUMN "activities"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "activities"."account_id" IS 'Account touched. Denormalised alongside the deal so account-level history survives a deleted opportunity.';
COMMENT ON COLUMN "activities"."deal_id" IS 'Deal touched. Null for relationship work not tied to an opportunity.';
COMMENT ON COLUMN "activities"."contact_id" IS 'Person involved.';
COMMENT ON COLUMN "activities"."user_id" IS 'Rep who did it. Null for automated logging.';
COMMENT ON COLUMN "activities"."activity_type" IS 'call | email | meeting | note | task | demo. The mix of types per deal is the honest measure of engagement.';
COMMENT ON COLUMN "activities"."subject" IS 'Short description shown in the timeline.';
COMMENT ON COLUMN "activities"."body" IS 'Notes or the email body.';
COMMENT ON COLUMN "activities"."direction" IS 'inbound | outbound. Null for notes and tasks, which have no direction.';
COMMENT ON COLUMN "activities"."occurred_at" IS 'When it happened. Null for a task that has not been done.';
COMMENT ON COLUMN "activities"."due_at" IS 'When a task is due. Null for logged past activity.';
COMMENT ON COLUMN "activities"."completed_at" IS 'Completion time for a task.';
COMMENT ON COLUMN "activities"."duration_minutes" IS 'Length of a call or meeting.';

CREATE INDEX "idx_activities_deal_time"
ON "activities" ("deal_id", "occurred_at");
CREATE INDEX "idx_activities_user_due"
ON "activities" ("user_id", "due_at");
CREATE INDEX "idx_activities_account_time"
ON "activities" ("account_id", "occurred_at");

CREATE TABLE IF NOT EXISTS "quotes" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Deal being quoted. Several quotes per deal is normal; negotiation is iterative.
	"deal_id" BIGINT NOT NULL,
	-- Customer-facing reference quoted in emails and purchase orders.
	"quote_number" VARCHAR(40) NOT NULL UNIQUE,
	-- Revision number. New versions are new rows, because the customer may be holding a printout of version 2.
	"version" SMALLINT NOT NULL DEFAULT 1,
	-- draft | sent | accepted | declined | expired. Only one accepted quote per deal, enforced in the application.
	"status" VARCHAR(20) NOT NULL DEFAULT 'draft',
	-- ISO 4217, snapshotted from the deal at creation.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Sum of line amounts before discount, in minor units.
	"subtotal_minor" BIGINT NOT NULL DEFAULT 0,
	-- Quote-level discount, stored separately so approval thresholds have something to check.
	"discount_minor" BIGINT NOT NULL DEFAULT 0,
	-- Final quoted amount, stored rather than derived so a reprice of the catalogue cannot alter a sent quote.
	"total_minor" BIGINT NOT NULL DEFAULT 0,
	-- Expiry date, which is the only leverage a rep has at quarter end.
	"valid_until" DATE,
	-- When it went to the customer.
	"sent_at" TIMESTAMP,
	-- Acceptance time, usually the trigger for moving the deal to a won stage.
	"accepted_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "quotes" IS 'A priced proposal at a point in time. Every total is snapshotted because a quote is a commitment: it must read the same next month even after the price book has changed.';
COMMENT ON COLUMN "quotes"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "quotes"."deal_id" IS 'Deal being quoted. Several quotes per deal is normal; negotiation is iterative.';
COMMENT ON COLUMN "quotes"."quote_number" IS 'Customer-facing reference quoted in emails and purchase orders.';
COMMENT ON COLUMN "quotes"."version" IS 'Revision number. New versions are new rows, because the customer may be holding a printout of version 2.';
COMMENT ON COLUMN "quotes"."status" IS 'draft | sent | accepted | declined | expired. Only one accepted quote per deal, enforced in the application.';
COMMENT ON COLUMN "quotes"."currency_code" IS 'ISO 4217, snapshotted from the deal at creation.';
COMMENT ON COLUMN "quotes"."subtotal_minor" IS 'Sum of line amounts before discount, in minor units.';
COMMENT ON COLUMN "quotes"."discount_minor" IS 'Quote-level discount, stored separately so approval thresholds have something to check.';
COMMENT ON COLUMN "quotes"."total_minor" IS 'Final quoted amount, stored rather than derived so a reprice of the catalogue cannot alter a sent quote.';
COMMENT ON COLUMN "quotes"."valid_until" IS 'Expiry date, which is the only leverage a rep has at quarter end.';
COMMENT ON COLUMN "quotes"."sent_at" IS 'When it went to the customer.';
COMMENT ON COLUMN "quotes"."accepted_at" IS 'Acceptance time, usually the trigger for moving the deal to a won stage.';

CREATE UNIQUE INDEX "uq_quotes_deal_version"
ON "quotes" ("deal_id", "version");

CREATE TABLE IF NOT EXISTS "quote_line_items" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent quote.
	"quote_id" BIGINT NOT NULL,
	-- Catalogue identifier, as text. The product catalogue is a separate system and this schema only needs the reference.
	"product_code" VARCHAR(60) NOT NULL,
	-- Line text as printed, snapshotted from the catalogue.
	"description" VARCHAR(255) NOT NULL,
	-- Units quoted. Decimal because services are sold in fractional days.
	"quantity" DECIMAL(12,2) NOT NULL DEFAULT 1,
	-- List price per unit at the time of quoting, in minor units.
	"unit_price_minor" BIGINT NOT NULL,
	-- Line-level discount. Kept as a percentage because that is how discount approval policies are written.
	"discount_percent" DECIMAL(5,2) NOT NULL DEFAULT 0,
	-- Computed line total after discount, stored so the printed document and the database always agree.
	"amount_minor" BIGINT NOT NULL DEFAULT 0,
	-- Subscription term for recurring lines, which is what separates annual contract value from total contract value.
	"term_months" SMALLINT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "quote_line_items" IS 'The line-by-line arithmetic of a quote. Prices and descriptions are copied from the catalogue rather than referenced, because a quote sent in March must still show March prices in September.';
COMMENT ON COLUMN "quote_line_items"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "quote_line_items"."quote_id" IS 'Parent quote.';
COMMENT ON COLUMN "quote_line_items"."product_code" IS 'Catalogue identifier, as text. The product catalogue is a separate system and this schema only needs the reference.';
COMMENT ON COLUMN "quote_line_items"."description" IS 'Line text as printed, snapshotted from the catalogue.';
COMMENT ON COLUMN "quote_line_items"."quantity" IS 'Units quoted. Decimal because services are sold in fractional days.';
COMMENT ON COLUMN "quote_line_items"."unit_price_minor" IS 'List price per unit at the time of quoting, in minor units.';
COMMENT ON COLUMN "quote_line_items"."discount_percent" IS 'Line-level discount. Kept as a percentage because that is how discount approval policies are written.';
COMMENT ON COLUMN "quote_line_items"."amount_minor" IS 'Computed line total after discount, stored so the printed document and the database always agree.';
COMMENT ON COLUMN "quote_line_items"."term_months" IS 'Subscription term for recurring lines, which is what separates annual contract value from total contract value.';

CREATE INDEX "idx_quote_lines_quote"
ON "quote_line_items" ("quote_id");

CREATE TABLE IF NOT EXISTS "forecasts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Rep or manager the forecast belongs to.
	"user_id" BIGINT NOT NULL,
	-- First day of the forecast period, usually a quarter.
	"period_start" DATE NOT NULL,
	-- Last day of the period.
	"period_end" DATE NOT NULL,
	-- pipeline | best_case | commit | closed. Commit is a promise, best case is an aspiration, and reporting them as one number is how forecasts lose credibility.
	"category" VARCHAR(20) NOT NULL DEFAULT 'commit',
	-- Submitted amount in minor units for this category.
	"amount_minor" BIGINT NOT NULL DEFAULT 0,
	-- ISO 4217 for the submitted figure.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Submission time. Rows are never updated — a revised forecast is a new row, so the week-by-week movement stays visible.
	"submitted_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "forecasts" IS 'Point-in-time forecast submissions per user, period and category. Appending rather than updating is the whole value: a manager needs to see that a commit number quietly fell by thirty percent over three weeks.';
COMMENT ON COLUMN "forecasts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "forecasts"."user_id" IS 'Rep or manager the forecast belongs to.';
COMMENT ON COLUMN "forecasts"."period_start" IS 'First day of the forecast period, usually a quarter.';
COMMENT ON COLUMN "forecasts"."period_end" IS 'Last day of the period.';
COMMENT ON COLUMN "forecasts"."category" IS 'pipeline | best_case | commit | closed. Commit is a promise, best case is an aspiration, and reporting them as one number is how forecasts lose credibility.';
COMMENT ON COLUMN "forecasts"."amount_minor" IS 'Submitted amount in minor units for this category.';
COMMENT ON COLUMN "forecasts"."currency_code" IS 'ISO 4217 for the submitted figure.';
COMMENT ON COLUMN "forecasts"."submitted_at" IS 'Submission time. Rows are never updated — a revised forecast is a new row, so the week-by-week movement stays visible.';

CREATE INDEX "idx_forecasts_user_period"
ON "forecasts" ("user_id", "period_start", "category", "submitted_at");

CREATE TABLE IF NOT EXISTS "custom_field_definitions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- account | contact | deal | lead. Which record type this field is attached to.
	"entity_type" VARCHAR(20) NOT NULL,
	-- Key used inside the custom_fields document on that entity.
	"field_key" VARCHAR(60) NOT NULL,
	-- Label shown on the record page.
	"label" VARCHAR(160) NOT NULL,
	-- text | number | date | boolean | picklist | currency. Drives validation and the filter operators offered.
	"field_type" VARCHAR(20) NOT NULL DEFAULT 'text',
	-- Allowed values for a picklist. Null for other types.
	"options" JSONB,
	-- Enforced by the application, since the values live in a JSON document.
	"is_required" BOOLEAN NOT NULL DEFAULT false,
	-- Display order on the layout.
	"position" SMALLINT NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "custom_field_definitions" IS 'Definitions only; the values sit in custom_fields on each record. Every CRM deployment invents fields nobody anticipated, and this pair — typed definitions as rows, values as JSON — adds them without a migration and without an EAV join on every read.';
COMMENT ON COLUMN "custom_field_definitions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "custom_field_definitions"."entity_type" IS 'account | contact | deal | lead. Which record type this field is attached to.';
COMMENT ON COLUMN "custom_field_definitions"."field_key" IS 'Key used inside the custom_fields document on that entity.';
COMMENT ON COLUMN "custom_field_definitions"."label" IS 'Label shown on the record page.';
COMMENT ON COLUMN "custom_field_definitions"."field_type" IS 'text | number | date | boolean | picklist | currency. Drives validation and the filter operators offered.';
COMMENT ON COLUMN "custom_field_definitions"."options" IS 'Allowed values for a picklist. Null for other types.';
COMMENT ON COLUMN "custom_field_definitions"."is_required" IS 'Enforced by the application, since the values live in a JSON document.';
COMMENT ON COLUMN "custom_field_definitions"."position" IS 'Display order on the layout.';

CREATE UNIQUE INDEX "uq_custom_field_key"
ON "custom_field_definitions" ("entity_type", "field_key");

